    /** Rows of the caller's institutions only (api/README "Authorization"). */
    public static SqlFragment scope(DataScope scope) {
        return new SqlFragment(SCOPE, Map.of("scopeAll", scope.all(), "scopeIds", scope.institutionArray()));
    }

    private static List<Object> sortValues(SortSpec sort, LmsCourseEntity e) {
        return sort.orders().stream().map(o -> SORT_VALUES.get(o.field().name()).apply(e)).toList();
    }

    private static LmsCourseEntity map(ResultSet rs, int row) throws SQLException {
        return LmsCourseEntity.builder()
                .id(rs.getObject("id", UUID.class))
                .tenantId(rs.getObject("tenant_id", UUID.class))
                .institutionId(rs.getObject("institution_id", UUID.class))
                .title(rs.getString("title"))
                .shortIntroduction(rs.getString("short_introduction"))
                .description(rs.getString("description"))
                .imageFileId(rs.getObject("image_file_id", UUID.class))
                .videoUrl(rs.getString("video_url"))
                .categoryId(rs.getObject("category_id", UUID.class))
                .status(rs.getString("status"))
                .isPublished(rs.getObject("is_published", Boolean.class))
                .publishedOn(rs.getObject("published_on", LocalDate.class))
                .isUpcoming(rs.getObject("is_upcoming", Boolean.class))
                .isFeatured(rs.getObject("is_featured", Boolean.class))
                .disableSelfLearning(rs.getObject("disable_self_learning", Boolean.class))
                .enforceLessonOrder(rs.getObject("enforce_lesson_order", Boolean.class))
                .certificationEnabled(rs.getObject("certification_enabled", Boolean.class))
                .paidCertificate(rs.getObject("paid_certificate", Boolean.class))
                .defaultEvaluatorId(rs.getObject("default_evaluator_id", UUID.class))
                .isPaid(rs.getObject("is_paid", Boolean.class))
                .price(rs.getBigDecimal("price"))
                .currencyId(rs.getObject("currency_id", UUID.class))
                .priceUsd(rs.getBigDecimal("price_usd"))
                .cardGradient(rs.getString("card_gradient"))
                .timezone(rs.getString("timezone"))
                .publishNotificationSent(rs.getObject("publish_notification_sent", Boolean.class))
                .enrollmentCount(rs.getObject("enrollment_count", Integer.class))
                .lessonCount(rs.getObject("lesson_count", Integer.class))
                .averageRating(rs.getBigDecimal("average_rating"))
                .code(rs.getString("code"))
                .stateStandardCode(rs.getString("state_standard_code"))
                .credits(rs.getBigDecimal("credits"))
                .prerequisites(rs.getString("prerequisites"))
                .corequisites(rs.getString("corequisites"))
                .effectiveFrom(rs.getObject("effective_from", LocalDate.class))
                .lifecycleStatus(rs.getString("lifecycle_status"))
                .deactivatedOn(rs.getObject("deactivated_on", LocalDate.class))
                .versionMajor(rs.getObject("version_major", Integer.class))
                .versionMinor(rs.getObject("version_minor", Integer.class))
                .previousVersionId(rs.getObject("previous_version_id", UUID.class))
                .rootCourseId(rs.getObject("root_course_id", UUID.class))
                .authorComments(rs.getString("author_comments"))
                .externalRef(rs.getString("external_ref"))
                .nominalDuration(rs.getObject("nominal_duration", Integer.class))
                .deliveryModality(rs.getString("delivery_modality"))
                .isShared(rs.getObject("is_shared", Boolean.class))
                .contentUpdatedAt(rs.getObject("content_updated_at", OffsetDateTime.class))
                .gradeDisplay(rs.getString("grade_display"))
                .gradingSchemeId(rs.getObject("grading_scheme_id", UUID.class))
                .isInCatalog(rs.getObject("is_in_catalog", Boolean.class))
                .catalogDescription(rs.getString("catalog_description"))
                .catalogVisibleFrom(rs.getObject("catalog_visible_from", OffsetDateTime.class))
                .catalogVisibleUntil(rs.getObject("catalog_visible_until", OffsetDateTime.class))
                .outline(rs.getString("outline"))
                .workloadHours(rs.getObject("workload_hours", Integer.class))
                .catalogStatus(rs.getString("catalog_status"))
                .createdAt(rs.getObject("created_at", OffsetDateTime.class))
                .createdBy(rs.getObject("created_by", UUID.class))
                .updatedAt(rs.getObject("updated_at", OffsetDateTime.class))
                .updatedBy(rs.getObject("updated_by", UUID.class))
                .deletedAt(rs.getObject("deleted_at", OffsetDateTime.class))
                .rowVersion(rs.getInt("row_version"))
                .build();
    }

    private static FieldSpec field(String name, String column, ValueType type) {
        return new FieldSpec(name, column, type);
    }

    private static Map<String, FieldSpec> fields(FieldSpec... specs) {
        return Arrays.stream(specs).collect(Collectors.toUnmodifiableMap(FieldSpec::name, s -> s));
    }
